--- sample 1 ---
{
  "a_failing_chord_carries_the_originating": {
    "score": "yes",
    "reasoning": "Chord errors now retain the originating exception as their cause. For a group chord body, `_handle_group_chord_error` unwraps that cause and invokes each task's errbacks and failure storage with the original exception, implementing actual task/result-queue behavior."
  },
  "the_worker_can_be_told_not_to_prefetch": {
    "score": "no",
    "reasoning": "The configuration and CLI switch are present, but honoring the option is gated only on whether the channel QoS object has `can_consume`. Other virtual transports may expose that method, so the implementation does not explicitly restrict the behavior to Redis brokers."
  },
  "the_consumer_cancels_requests_in_flight": {
    "score": "yes",
    "reasoning": "`Consumer.cancel_active_requests` iterates active, non-successful requests and cancels them. `Request.cancel` now accepts `emit_retry`, allowing each cancellation to decide whether a retry state and signal should be emitted."
  },
  "control_and_event_queues_each_declare_du": {
    "score": "yes",
    "reasoning": "Control queues use `control_queue_durable` and `control_queue_exclusive`, while event queues independently use `event_queue_durable` and `event_queue_exclusive`. Both combinations are validated against being simultaneously durable and exclusive."
  },
  "the_queue_created_for_an_unknown_route_t": {
    "score": "yes",
    "reasoning": "`Queues.new_missing` applies `create_missing_queue_type` through `x-queue-type`, and the value can come from explicit `Queues` parameters or `task_create_missing_queue_type` configuration. The missing queue's exchange type is similarly configurable."
  },
  "consumption_admission_is_bounded_by_in_f": {
    "score": "yes",
    "reasoning": "The wrapped channel `can_consume` rejects admission once `reserved_requests` reaches the effective maximum concurrency, including the autoscaler's current maximum when available. Below that limit it delegates to the original `can_consume` check."
  },
  "binding_delayed_delivery_queues_retries": {
    "score": "yes",
    "reasoning": "`RETRIED_EXCEPTIONS` defines the transient failures, `retry_over_time` catches that set, and queue binding re-raises those exceptions directly so the entire delayed-delivery setup is retried."
  },
  "django_teardown_suppresses_a_vanished_co": {
    "score": "yes",
    "reasoning": "Database pool teardown suppresses only `KeyError` from `close_pool`, covering an already-vanished shared pool. `close_cache` no longer catches `TypeError` or `AttributeError`, so cache teardown failures propagate."
  },
  "a_chord_body_receives_an_identity_derive": {
    "score": "yes",
    "reasoning": "After freezing the chord body, a body lacking an ID is assigned `bodyres.id`, which is the identity produced by freezing the actual body with the chord's requested task ID, rather than an unrelated placeholder."
  },
  "the_eager_application_path_builds_its_re": {
    "score": "yes",
    "reasoning": "The eager request now includes `parent_id` and `root_id`. Missing lineage is read from `_task_stack.top.request` when a calling task exists, with the eager task's own ID used as the root only when no inherited root is available."
  },
  "a_corrupted_stored_schedule_is_rebuilt_r": {
    "score": "yes",
    "reasoning": "Schedule loading now recognizes EOF and pickle unpickling failures in addition to the prior errors. Corrupted `entries` are replaced with an empty schedule, while corrupted metadata is logged and subsequently rewritten."
  },
  "termination_on_failure_and_on_timeout_re": {
    "score": "no",
    "reasoning": "The changes only add early returns for requests already marked cancelled or revoked. Hard timeout still uses its bespoke backend failure reporting, while failure termination follows a separate revoked-reporting branch; no shared reporting path is introduced."
  }
}

--- sample 2 ---
{
  "a_failing_chord_carries_the_originating": {
    "score": "yes",
    "reasoning": "ChordError wrappers now retain the originating exception as __cause__, and group chord bodies unwrap that cause so their tasks and errbacks are failed with the original exception. This is implemented in the Celery backend/task-queue paths."
  },
  "the_worker_can_be_told_not_to_prefetch": {
    "score": "no",
    "reasoning": "The setting and CLI option exist, but honoring it is gated only on the channel QoS object exposing can_consume. There is no Redis transport check, so other virtual transports with that method can honor it as well."
  },
  "the_consumer_cancels_requests_in_flight": {
    "score": "yes",
    "reasoning": "Consumer.cancel_active_requests iterates active requests and cancels them, while Request.cancel now has an emit_retry parameter. Late-acknowledged requests are canceled with retry announcement disabled."
  },
  "control_and_event_queues_each_declare_du": {
    "score": "yes",
    "reasoning": "Control mailbox queues use control_queue_durable and control_queue_exclusive, while event receiver queues independently use event_queue_durable and event_queue_exclusive. Conflicting durable/exclusive combinations are also rejected."
  },
  "the_queue_created_for_an_unknown_route_t": {
    "score": "yes",
    "reasoning": "Automatically created queues take their queue type from create_missing_queue_type, supplied explicitly to Queues or obtained from task_create_missing_queue_type. Non-classic types receive the appropriate x-queue-type argument."
  },
  "consumption_admission_is_bounded_by_in_f": {
    "score": "yes",
    "reasoning": "The patched can_consume rejects admission when reserved_requests reaches the effective autoscaler, controller, or pool concurrency limit, and otherwise invokes the original can_consume check."
  },
  "binding_delayed_delivery_queues_retries": {
    "score": "yes",
    "reasoning": "RETRIED_EXCEPTIONS defines the transient failures, retry_over_time catches that set, and queue binding re-raises those exceptions directly so the complete setup is retried."
  },
  "django_teardown_suppresses_a_vanished_co": {
    "score": "yes",
    "reasoning": "Database pool closure suppresses KeyError for an already-vanished pool, while close_cache no longer catches TypeError or AttributeError, allowing cache teardown failures to propagate."
  },
  "a_chord_body_receives_an_identity_derive": {
    "score": "yes",
    "reasoning": "The chord freezes its body with the chord task identity and, when the body itself lacks an ID, assigns the ID from the frozen body result rather than leaving or manufacturing an unrelated placeholder."
  },
  "the_eager_application_path_builds_its_re": {
    "score": "yes",
    "reasoning": "Task.apply now builds parent_id and root_id before constructing its eager request, consulting _task_stack.top and its request whenever explicit lineage values are absent."
  },
  "a_corrupted_stored_schedule_is_rebuilt_r": {
    "score": "yes",
    "reasoning": "The schedule load error set now includes EOF and pickle unpickling failures, and _create_schedule handles those failures by recreating the entries mapping. Corrupted metadata is also logged rather than silently ignored."
  },
  "termination_on_failure_and_on_timeout_re": {
    "score": "no",
    "reasoning": "The change adds early-return guards for already canceled or revoked requests, but hard-timeout reporting still has its bespoke mark_as_failure and task-failed event logic. Failure and timeout reporting were not refactored through one shared reporting path."
  }
}

